const $=s=>document.querySelector(s),data=portfolioData;
const esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=v=>{if(typeof v!=='string'||!v.trim())return '';try{const u=new URL(v,location.href);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const bio=v=>esc(v).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
const projects=data.projects.filter(p=>p.permission==='Boleh ditampilkan');
let active=Math.max(0,projects.findIndex(p=>p.id==='project-22')),filter='all',projectQuery='';
const types={web:'Website',app:'Web App',social:'Konten Medsos',saas:'SaaS'};
const visible=()=>projects.map((p,i)=>({...p,index:i})).filter(p=>(filter==='all'||p.types.includes(types[filter]))&&(!projectQuery||[p.brand,p.title,p.en?.title,...p.tools].join(' ').toLocaleLowerCase().includes(projectQuery.toLocaleLowerCase())));
const roleText='Menangani seluruh proses: perencanaan, desain, pengembangan, pengujian, dan deployment.';
function projectMark(p){return p.logo?`<img class="real-logo" src="assets/${esc(p.logo)}" alt="" width="96" height="64">`:`<span class="project-wordmark" aria-hidden="true">${esc(p.brand)}</span>`}
function renderCarousel(list,hadFocus){
 const rail=$('#rail'),key=list.map(p=>p.id).join('|');
 if(rail.dataset.collection!==key){rail.innerHTML=list.map(p=>`<button class="brand" data-index="${p.index}" aria-pressed="false" aria-label="${esc(p.brand)}"><span class="project-mark">${projectMark(p)}</span><b>${esc(p.brand)}</b><small>${esc(p.types.join(' · '))}</small></button>`).join('');rail.dataset.collection=key}
 const position=list.findIndex(p=>p.index===active),count=list.length;
 rail.querySelectorAll('.brand').forEach((card,i)=>{let slot=(i-position+count)%count;if(slot>=(count+1)/2)slot-=count;const distance=Math.abs(slot);card.style.setProperty('--slot',slot);card.dataset.distance=String(Math.min(distance,4));card.classList.toggle('active',slot===0);card.setAttribute('aria-pressed',String(slot===0));card.tabIndex=slot===0?0:-1;card.setAttribute('aria-hidden',String(distance>2));card.inert=distance>2});
 rail.scrollLeft=0;if(hadFocus)rail.querySelector('.active')?.focus({preventScroll:true});
}
function render(){
 const list=visible(),hadFocus=document.activeElement?.matches('.brand');
 if(list.length&&!list.some(p=>p.index===active))active=list[0].index;
 $('#projectcount').textContent=list.length+' proyek';$('#viewbuttons').hidden=true;$('#viewbuttons').style.display='none';
 $('#prev').disabled=$('#next').disabled=list.length<2;
 renderCarousel(list,hadFocus);
 window.renderProjectEvidence?.(list.length?projects[active]:null);
 document.querySelectorAll('[data-featured-project]').forEach(b=>b.setAttribute('aria-pressed',String(!!list.length&&b.dataset.featuredProject===projects[active].id)));
 if(document.querySelector('#content-gallery'))document.querySelector('#content-gallery').hidden=true;
 if(!list.length){$('.project').hidden=true;$('#visual').innerHTML='';$('#counter').textContent='';$('.hint').textContent=filter==='social'?'Detail pekerjaan kreatif akan ditambahkan bertahap.':(projectQuery?'Tidak ada proyek yang cocok. Coba kata kunci lain.':'Belum ada proyek pada kategori ini.');return}
 if(document.querySelector('#content-gallery'))document.querySelector('#content-gallery').hidden=true;
 if(filter==='social'&&projects[active].contentManagement&&window.renderContentGallery){$('.project').hidden=true;$('.hint').textContent='Pilih format dan jelajahi koleksi konten.';window.renderContentGallery(projects[active]);return}
 $('.project').hidden=false;$('.hint').textContent='Geser untuk memilih · koleksi berputar tanpa ujung.';
 const p=projects[active];$('#title').textContent=p.brand;$('#desc').textContent=p.need;$('#role').textContent=p.contribution||roleText;$('#category').textContent=p.title;$('#relationship').textContent=p.relationship;$('#counter').textContent=String(list.findIndex(x=>x.index===active)+1).padStart(2,'0')+' / '+String(list.length).padStart(2,'0');
 const meta=document.querySelector('#project-meta');meta.innerHTML=`<div><small>TAHUN</small><b>${esc(p.year)}</b></div><div><small>STATUS</small><b>${esc(p.status)}</b></div>${p.tools.length?`<div class="project-tools"><small>TOOLS</small><div>${p.tools.map(t=>`<span>${esc(t)}</span>`).join('')}</div></div>`:''}`;
 const cover=p.cover&&!p.restricted?`<button class="project-preview-open" data-preview="${p.index??active}" aria-label="Perbesar pratinjau ${esc(p.brand)}"><img class="project-cover" src="assets/projects/${esc(p.cover)}" alt="Pratinjau proyek ${esc(p.brand)}" width="1348" height="926"><span class="preview-expand">Perbesar tampilan <span aria-hidden="true">↗</span></span></button>`:'';
 $('#stage').style.background='var(--stage)';$('#stage .tag').textContent=p.restricted?'PROYEK INTERNAL · RINGKASAN PUBLIK':p.cover?'PRATINJAU PROYEK':'RINGKASAN PRODUK';
 $('#visual').innerHTML=`<article class="project-showcase">${cover||`<div class="project-preview-empty"><span class="preview-emblem" aria-hidden="true">${p.restricted?'◇':'◈'}</span><h3>${esc(p.brand)}</h3><p>${p.restricted?'Data, tampilan internal, dan tautan aplikasi tidak dipublikasikan.':'Produk sedang dibangun; akses publik menyusul.'}</p></div>`}<div class="project-chapter"><span>${esc(p.types.join(' · '))}</span><span class="project-status">${esc(p.status)}</span></div></article>`;
 const details=$('.projectinfo .details');details.innerHTML=`${p.solution&&p.solution!==p.need?`<div class="project-solution"><small>Solusi yang dibangun</small><p>${esc(p.solution)}</p></div>`:''}${p.features.length?`<div class="project-capabilities"><small>Fitur utama</small><ul>${p.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div>`:''}<div><small>Kontribusi saya</small><p id="role">${esc(p.contribution||roleText)}</p></div><div class="project-kind"><small>Jenis karya</small><p id="category">${esc(p.title)}</p></div>`;
 if(p.caseStudy&&!p.portfolioEvidence){const c=p.caseStudy;details.insertAdjacentHTML('beforeend',`<details class="project-case"><summary>Studi kasus <span>+</span></summary>${[['audience','Target pengguna'],['challenge','Tantangan'],['approach','Pendekatan'],['outcome','Hasil & status'],['period','Periode penugasan']].filter(([key])=>c[key]).map(([key,label])=>`<div><small>${label}</small><p>${esc(c[key])}</p></div>`).join('')}</details>`)}
 let actions=$('.project-actions');if(!actions){actions=document.createElement('div');actions.className='project-actions';$('.projectinfo').append(actions)}
 actions.innerHTML=!p.restricted&&(p.status!=='Dalam pengembangan'||p.demoAvailable)&&url(p.live)?`<a class="project-visit" href="${esc(url(p.live))}" target="_blank" rel="noopener noreferrer">${(p.status==='Demo tersedia'||p.demoAvailable)?'Coba demo ↗':'Buka website asli ↗'}</a><button class="project-contact" data-go="about">Diskusikan proyek serupa <span aria-hidden="true">↗</span></button>`:'';
 $('.projectinfo .note').textContent=p.restricted?'Aplikasi internal klien. Ringkasan publik tidak membuka data operasional atau akses privat.':p.id==='project-13'?'Demo KabarKelas tersedia · progres yang dilaporkan 75% per Oktober 2026 · kesiapan produksi belum terverifikasi.':p.status==='Demo tersedia'?'Demo untuk eksplorasi dan umpan balik; bukan klaim produk siap produksi.':p.status==='Dalam pengembangan'?'Produk masih dalam pengembangan; akses publik belum dikonfirmasi.':'';
 $('#visual').classList.remove('fade');void $('#visual').offsetWidth;$('#visual').classList.add('fade');
}
function profile(){const p=data.profile;
const cv=p.cv||url(p.cvDrive||'');
$('.profiletext').innerHTML=`<div class="profile-kicker"><span class="eyebrow">MAIN CHARACTER</span><span class="character-status">Terbuka untuk kolaborasi</span></div><h2>${esc(p.name)}</h2><div class="character-class">${esc(p.headline)}</div><p class="character-bio">${bio(p.bio)}</p><div class="profilefacts"><div><small>BASE</small><p>${esc(p.city)}</p></div><div><small>LANGUAGES</small><p>${esc(p.languages)}</p></div><div class="availability-fact"><small>AVAILABLE FOR</small><p>${esc(p.availability)}</p></div></div><button class="skills-shortcut" data-go="skillset"><span>✧</span><div>Skills &amp; Abilities<small>Jelajahi tools dan kemampuan saya</small></div><b>→</b></button><div class="profile-actions"><button class="profile-primary" data-go="portofolio">Lihat Portfolio <span>↗</span></button>${cv?`<a class="profile-secondary" href="${esc(cv)}" download>Unduh CV <span>↓</span></a>`:'<button class="profile-secondary" disabled aria-describedby="cv-status">Unduh CV <span>↓</span></button>'}<button class="profile-secondary" data-go="about">Hubungi Saya <span>↗</span></button></div><p id="cv-status" class="cv-hint">${cv?'CV ringkas · pengalaman, kemampuan, dan karya pilihan.':'Folder Drive untuk CV PDF & portfolio PDF belum ditambahkan.'}</p>`;
const socials=[{name:'WhatsApp',label:'Mulai percakapan',icon:'WA',href:p.whatsapp?'https://wa.me/'+p.whatsapp.replace(/\D/g,''):''},{name:'Instagram',label:'Karya & cerita sehari-hari',icon:'IG',href:url(p.instagram||'')},{name:'Threads',label:'Ide & percakapan',icon:'@',href:url(p.threads||'')},{name:'Email',label:p.email||'Email profesional',icon:'✉',href:p.email?'mailto:'+p.email:''},{name:'LinkedIn',label:'Terhubung secara profesional',icon:'in',href:url(p.linkedin||'')},{name:'Website Studio',label:'desainindongmas',icon:'↗',href:url(p.website||'')}];
$('#about-contact').innerHTML=`<div class="contact-intro"><div class="eyebrow">BEHIND THE CHARACTER</div><h2>Kenalan dulu.<br>Lalu, mulai sesuatu.</h2><p>${bio(p.bio)}</p><div class="studio-note"><img src="assets/ddm-logo.png" alt="Logo desainindongmas"><p>Saya mengelola <strong>desainindongmas</strong>, studio kreatif dan teknologi. Portofolio ini menampilkan karya dan kontribusi saya secara pribadi.</p></div><button class="profile-secondary" data-go="profil">Lihat Profile ←</button></div><div class="contact-hub"><div class="eyebrow">LET’S CONNECT</div><h3>Pilih tempat untuk menyapa.</h3><div class="contact-options">${socials.map(a=>a.href?`<a class="contact-option" href="${esc(a.href)}" ${a.name==='Email'?'':'target="_blank" rel="noopener noreferrer"'}><span class="contact-symbol">${esc(a.icon)}</span><div><b>${esc(a.name)}</b><small>${esc(a.label)}</small></div><span>↗</span></a>`:`<div class="contact-option unavailable" aria-disabled="true"><span class="contact-symbol">${esc(a.icon)}</span><div><b>${esc(a.name)}</b><small>Tautan belum ditambahkan</small></div><span>—</span></div>`).join('')}</div><p class="cv-hint">Terbuka untuk freelance, kolaborasi proyek, dan kesempatan kerja.</p></div>`;
 const period=value=>/^\d{4}$/.test(value)?value:/^\d{4}-\d{2}$/.test(value)?new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(value+'-01')):'';
 const journals=document.querySelectorAll('.journal');journals[0].innerHTML=`<div class="eyebrow">CHAPTER 01 / EXPERIENCE</div><h2>Pengalaman berkarya.</h2>${data.experience.map(e=>`<article class="timeline"><h3>${esc(e.company)}</h3><p><strong>${esc(e.role)}</strong>${e.mode?` · ${esc(e.mode)}`:''}</p><p><span>${esc(period(e.from))}</span> – <span>${e.current?'Sekarang':esc(period(e.to))}</span></p>${e.scope?`<p>${esc(e.scope)}</p>`:''}</article>`).join('')}`;
 journals[1].innerHTML=`<div class="eyebrow">CAPABILITIES / KNOWLEDGE</div><h2>Keahlian & pendidikan.</h2><div class="skills">${data.skills.map((s,i)=>`<div class="skillrow"><b>${String(i+1).padStart(2,'0')} / ${esc(s.name)}</b><p>${esc(s.tools)}</p><p>${esc(s.level)} · penilaian pribadi</p></div>`).join('')}</div><div class="education"><div class="eyebrow">EDUCATION ARCHIVE</div>${data.education.map(e=>`<h3>${esc(e.institution)}</h3><p>${esc(e.program)} · ${esc(e.kind)}</p><p>${e.to?'Selesai '+esc(new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(e.to+'-01'))):'Periode belum diisi'}</p>`).join('')}</div>`;
}
function route(){let name=location.hash.slice(1)||'menu';if(!['menu','profil','portofolio','skillset','about'].includes(name))name='menu';document.querySelectorAll('[data-screen]').forEach(s=>s.hidden=s.dataset.screen!==name);window.scrollTo(0,0);if(name==='portofolio')render();document.title=(name==='menu'?data.profile.name:name==='profil'?'Profil':name==='skillset'?'Skills & Abilities':name==='about'?'About & Contact':'Portfolio')+' — Creative Archive'}
profile();document.addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)location.hash=b.dataset.go});window.addEventListener('hashchange',route);
let suppressRailClickUntil=0;
$('#rail').onclick=e=>{if(Date.now()<suppressRailClickUntil)return;const b=e.target.closest('[data-index]');if(b){active=+b.dataset.index;render()}};
function move(n){const list=visible();if(!list.length)return;active=list[(list.findIndex(p=>p.index===active)+n+list.length)%list.length].index;render()}
$('#prev').onclick=()=>move(-1);$('#next').onclick=()=>move(1);$('#rail').onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}};
let startX=0,startY=0,railPointer=null;$('#rail').onpointerdown=e=>{startX=e.clientX;startY=e.clientY;railPointer=e.pointerId};$('#rail').onpointerup=e=>{if(railPointer!==e.pointerId)return;railPointer=null;if(Math.abs(e.clientX-startX)>40&&Math.abs(e.clientY-startY)<65){suppressRailClickUntil=Date.now()+350;move(e.clientX<startX?1:-1)}};$('#rail').onpointercancel=()=>{railPointer=null};
let wheelDelta=0,lastWheelMove=0;$('#rail').addEventListener('wheel',e=>{if(Math.abs(e.deltaX)<=Math.abs(e.deltaY))return;e.preventDefault();if(Date.now()-lastWheelMove<240)return;wheelDelta+=e.deltaX;if(Math.abs(wheelDelta)>35){move(wheelDelta>0?1:-1);wheelDelta=0;lastWheelMove=Date.now()}},{passive:false});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;const list=visible();if(list.length)active=list[0].index;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});render()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-preview]');if(!b)return;const p=projects[+b.dataset.preview];if(!p?.cover||p.restricted)return;$('#modalcontent').innerHTML=`<h2 id="preview-title">${esc(p.brand)}</h2><img class="expanded-project-preview" src="assets/projects/${esc(p.cover)}" alt="Pratinjau proyek ${esc(p.brand)}">`;$('#modal').setAttribute('aria-labelledby','preview-title');$('#modal').showModal()});
$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});route();
